window.EXAM_DATA = {"demo": "sample", "papers": [{"id": "s-en", "subject": "영어", "title": "2026 내신 대비 예시 · 고2 영어", "kind": "내신", "grade": "고2", "ym": "2026-10", "by": "김지수", "date": "2026-10-20", "units": [{"id": "u01", "numbers": "18", "type_label": "글의 목적", "genre": "기타", "passage": "Dear Students,\nStarting next Monday, the school library will stay open until 8 p.m. on weekdays. Many of you told us that the library closes too early for after-school study. To make this possible, we need a few student volunteers to help at the front desk from 5 p.m. to 8 p.m. Volunteers will receive service hours and can choose the days that suit them. If you are interested, please fill out the form at the library desk by this Friday.\nSincerely,\nMs. Kim, Librarian", "questions": [{"number": "18", "stem": "다음 글의 목적으로 가장 적절한 것은?", "choices": ["도서관 휴관일 변경을 안내하려고", "도서관 운영 시간 연장에 필요한 봉사자를 모집하려고", "도서 대출 규칙을 설명하려고", "방과 후 수업 신청을 독려하려고", "도서관 시설 공사를 알리려고"]}], "has_figure": false, "figure_desc": "", "confidence": "high", "note": ""}, {"id": "u02", "numbers": "22", "type_label": "글의 요지", "genre": "기타", "passage": "Many students stay up late before an exam, believing that more hours of study will lead to better scores. However, research on memory suggests the opposite. During deep sleep, the brain replays what we learned during the day and moves it into long-term memory. When we cut sleep short, this process is interrupted, and much of what we studied is lost. In other words, a good night's sleep is not a break from studying; it is part of studying. Students who protect their sleep before a test often remember more than those who study all night.", "questions": [{"number": "22", "stem": "다음 글의 요지로 가장 적절한 것은?", "choices": ["시험 전날에는 공부 시간을 늘리는 것이 효과적이다.", "시험 전 충분한 수면은 학습 내용을 기억하는 데 도움이 된다.", "깊은 잠은 몸의 피로를 푸는 데에만 필요하다.", "밤샘 공부는 집중력을 높여 준다.", "기억력은 타고나는 능력이다."]}], "has_figure": false, "figure_desc": "", "confidence": "high", "note": ""}, {"id": "u03", "numbers": "25", "type_label": "도표", "genre": "기타", "passage": "The graph above shows how many hours students in four grades spent reading for pleasure each week in 2021 and 2026.", "questions": [{"number": "25", "stem": "다음 도표의 내용과 일치하지 않는 것은?", "choices": ["①", "②", "③", "④", "⑤"]}], "has_figure": true, "figure_desc": "학년별(중3 · 고1 · 고2 · 고3) 주당 독서 시간 막대그래프, 2021년과 2026년 비교", "confidence": "high", "note": ""}, {"id": "u04", "numbers": "31", "type_label": "빈칸", "genre": "기타", "passage": "When we learn a new skill, we often want to move on as soon as we can do it once. But being able to do something once is very different from being able to do it well. Musicians, for example, keep practicing a piece long after they can play it without mistakes. They know that ________. Each extra round of practice makes the skill more automatic, so that it holds up even under pressure, such as on a stage in front of hundreds of people.", "questions": [{"number": "31", "stem": "다음 빈칸에 들어갈 말로 가장 적절한 것은?", "choices": ["talent matters more than effort", "one correct performance is not the finish line", "mistakes should be hidden from the audience", "practice is only for beginners", "playing alone is better than playing on stage"]}], "has_figure": false, "figure_desc": "", "confidence": "high", "note": ""}, {"id": "u05", "numbers": "36", "type_label": "글의 순서", "genre": "기타", "passage": "Most people think of forgetting as a simple failure of memory.\n\n(A) As a result, the important ideas stand out more clearly, and we can find them faster when we need them.\n\n(B) Scientists, however, now believe that the brain often forgets on purpose.\n\n(C) It clears away details we rarely use, such as the color of a stranger's shirt, to make room for new information.", "questions": [{"number": "36", "stem": "주어진 글 다음에 이어질 글의 순서로 가장 적절한 것을 고르시오.", "choices": ["(A) - (C) - (B)", "(B) - (A) - (C)", "(B) - (C) - (A)", "(C) - (A) - (B)", "(C) - (B) - (A)"]}], "has_figure": false, "figure_desc": "", "confidence": "high", "note": ""}]}, {"id": "s-ko", "subject": "국어", "title": "2026 내신 대비 예시 · 고2 국어", "kind": "내신", "grade": "고2", "ym": "2026-10", "by": "박소연", "date": "2026-10-21", "units": [{"id": "u01", "numbers": "1~3", "type_label": "독서 · 인문", "genre": "독서", "passage": "사람들은 자신이 이미 믿고 있는 생각을 뒷받침하는 정보에 더 쉽게 주목하는 경향이 있다. 이를 확증 편향이라고 한다. 확증 편향은 정보를 빠르게 처리하게 해 주는 장점이 있지만, 잘못된 판단을 굳히는 원인이 되기도 한다. 예를 들어 어떤 음식이 건강에 좋다고 믿는 사람은 그 음식의 효과를 다룬 기사만 골라 읽고, 반대되는 연구 결과는 대수롭지 않게 넘기기 쉽다. 이러한 편향을 줄이려면 자신의 생각과 반대되는 근거를 의도적으로 찾아보고, 그 근거가 왜 틀렸는지 설명할 수 있는지 스스로 점검하는 태도가 필요하다. 자신의 믿음이 반대 근거 앞에서도 유지된다면 그 믿음은 이전보다 단단해진다.", "questions": [{"number": "1", "stem": "윗글의 내용과 일치하지 않는 것은?", "choices": ["확증 편향은 정보 처리 속도와 관련이 있다.", "확증 편향은 판단을 굳히는 원인이 될 수 있다.", "확증 편향이 있으면 반대 근거를 가볍게 보기 쉽다.", "반대 근거를 찾아보는 태도는 편향을 줄인다.", "확증 편향은 누구에게서도 나타나지 않는다."]}], "has_figure": false, "figure_desc": "", "confidence": "high", "note": ""}, {"id": "u02", "numbers": "4~6", "type_label": "문학 · 현대시", "genre": "문학", "passage": "골목 끝 오래된 우체통은\n오늘도 빨간 입을 다물고 서 있다\n아무도 편지를 쓰지 않는 저녁\n바람만 그 입술을 두드리고 간다\n나는 주머니 속 접힌 종이를 만지작거리다\n끝내 넣지 못한 채 돌아선다\n불 켜진 창문들이 하나둘\n대신 안부를 묻는다\n- 예시로 쓴 시 「저녁 우체통」", "questions": [{"number": "4", "stem": "윗글에 대한 설명으로 가장 적절한 것은?", "choices": ["색채어를 통해 밝은 분위기를 만들고 있다.", "사물을 사람처럼 표현해 쓸쓸한 정서를 드러내고 있다.", "계절의 변화에 따라 시상을 전개하고 있다.", "명령형 어조로 의지를 드러내고 있다.", "대화 형식으로 갈등을 보여 주고 있다."]}], "has_figure": false, "figure_desc": "", "confidence": "high", "note": ""}]}], "pool": [{"id": "s1", "paperId": "s-en", "unitId": "u01", "group": "original", "subtype": "목적", "form": "5지", "stem": "다음 글의 목적으로 가장 적절한 것은?", "choices": ["도서관 이용 시간이 줄어드는 이유를 설명하려고", "방과 후 자율 학습 신청을 받으려고", "도서관 안내 데스크 봉사자를 모집하려고", "봉사 시간 인정 기준을 바꾸려고", "도서관 신청서 양식을 고치려고"], "answer": 3, "answer_text": "", "explanation": "운영 시간을 늘리기 위해 오후 5시부터 8시까지 안내 데스크를 도울 학생 봉사자가 필요하다고 했으므로 ③이 정답이다. ①은 이용 시간이 늘어나는 것과 반대이다.", "evidence": ["To make this possible, we need a few student volunteers to help at the front desk from 5 p.m. to 8 p.m."], "rubric": [], "flags": []}, {"id": "s2", "paperId": "s-en", "unitId": "u01", "group": "detail", "subtype": "내용 불일치", "form": "5지", "stem": "윗글의 내용과 일치하지 않는 것은?", "choices": ["다음 주 월요일부터 평일에 오후 8시까지 연다.", "학생들은 도서관이 너무 일찍 닫는다고 말했다.", "봉사자는 오후 5시부터 8시까지 안내 데스크를 돕는다.", "봉사자는 원하는 요일을 고를 수 있다.", "신청서는 이번 주 금요일까지 온라인으로 낸다."], "answer": 5, "answer_text": "", "explanation": "신청서는 도서관 안내 데스크에서 작성한다고 했으므로 ⑤가 일치하지 않는다.", "evidence": ["If you are interested, please fill out the form at the library desk by this Friday."], "rubric": [], "flags": []}, {"id": "s3", "paperId": "s-en", "unitId": "u01", "group": "writing", "subtype": "요약문 빈칸 쓰기", "form": "서답", "stem": "윗글의 내용을 한 문장으로 요약하고자 한다. 빈칸 (A), (B)에 들어갈 말을 윗글에서 찾아 각각 한 단어로 쓰시오.\nThe library needs student (A)________ for the front desk, and they will receive service (B)________.", "choices": [], "answer": 0, "answer_text": "(A) volunteers (B) hours", "explanation": "봉사자(volunteers)가 필요하고, 봉사자는 봉사 시간(service hours)을 받는다.", "evidence": ["Volunteers will receive service hours and can choose the days that suit them."], "rubric": [{"point": 2, "criterion": "(A)에 volunteers 를 정확히 씀"}, {"point": 2, "criterion": "(B)에 hours 를 정확히 씀"}], "flags": []}, {"id": "s4", "paperId": "s-en", "unitId": "u02", "group": "original", "subtype": "요지", "form": "5지", "stem": "다음 글의 요지로 가장 적절한 것은?", "choices": ["시험 전날에는 공부 시간을 최대한 늘려야 한다.", "깊은 잠은 낮의 피로를 푸는 데에만 쓰인다.", "충분한 잠은 배운 내용을 오래 기억하게 하는 공부의 일부이다.", "밤새 공부하는 습관은 시험 점수와 관계가 없다.", "기억력은 타고나는 것이라 노력으로 바뀌지 않는다."], "answer": 3, "answer_text": "", "explanation": "잠자는 동안 배운 내용이 장기 기억으로 옮겨지므로 충분한 잠은 공부의 일부라고 했다. 따라서 ③이 정답이다.", "evidence": ["In other words, a good night's sleep is not a break from studying; it is part of studying."], "rubric": [], "flags": []}, {"id": "s5", "paperId": "s-en", "unitId": "u02", "group": "main", "subtype": "제목", "form": "5지", "stem": "윗글의 제목으로 가장 적절한 것은?", "choices": ["Why All-Night Study Brings Top Scores", "Sleep: The Hidden Part of Studying", "How Dreams Show Our Daily Worries", "Short Breaks Make Long Study Possible", "Memory Tricks for Busy Students"], "answer": 2, "answer_text": "", "explanation": "잠이 공부의 일부라는 내용이므로 ②가 정답이다. ①은 글의 내용과 반대이다.", "evidence": ["During deep sleep, the brain replays what we learned during the day and moves it into long-term memory."], "rubric": [], "flags": []}, {"id": "s6", "paperId": "s-en", "unitId": "u02", "group": "detail", "subtype": "내용 일치", "form": "OX", "stem": "윗글의 내용과 일치하면 O, 일치하지 않으면 X를 고르시오.\n깊은 잠을 자는 동안 뇌는 낮에 배운 내용을 다시 떠올린다.", "choices": ["O", "X"], "answer": 1, "answer_text": "", "explanation": "깊은 잠을 자는 동안 뇌가 낮에 배운 것을 다시 재생한다고 했으므로 O 이다.", "evidence": ["During deep sleep, the brain replays what we learned during the day and moves it into long-term memory."], "rubric": [], "flags": []}, {"id": "s7", "paperId": "s-en", "unitId": "u02", "group": "main", "subtype": "주장", "form": "5지", "stem": "다음 글에서 필자가 주장하는 바로 가장 적절한 것은?", "choices": ["시험 전에는 잠을 충분히 자야 한다.", "잠을 줄이면 공부한 내용을 잃기 쉽다.", "공부 계획은 시험 한 달 전에 세워야 한다.", "깊은 잠을 자려면 운동을 해야 한다.", "시험 점수보다 공부 과정이 중요하다."], "answer": 1, "answer_text": "", "explanation": "시험 전 잠을 지키는 학생이 더 많이 기억한다는 내용이므로 ①이 정답이다.", "evidence": ["Students who protect their sleep before a test often remember more than those who study all night."], "rubric": [], "flags": ["solve_mismatch"]}, {"id": "s8", "paperId": "s-en", "unitId": "u04", "group": "original", "subtype": "구/절", "form": "5지", "stem": "다음 빈칸에 들어갈 말로 가장 적절한 것은?", "choices": ["audiences remember only the first mistake", "being able to do it once is only the beginning", "practice becomes useless after a point", "new pieces are easier than old ones", "stage fear disappears with talent"], "answer": 2, "answer_text": "", "explanation": "한 번 해내는 것과 잘하는 것은 다르다고 했으므로 ②가 정답이다.", "evidence": ["But being able to do something once is very different from being able to do it well."], "rubric": [], "flags": []}, {"id": "s9", "paperId": "s-en", "unitId": "u04", "group": "blank", "subtype": "한 단어", "form": "5지", "stem": "다음 빈칸에 들어갈 말로 가장 적절한 것은?\n\nWhen we learn a new skill, we often want to move on as soon as we can do it once. But being able to do something once is very different from being able to do it well. Musicians, for example, keep practicing a piece long after they can play it without mistakes. They know that one correct performance is not the finish line. Each extra round of practice makes the skill more ________, so that it holds up even under pressure, such as on a stage in front of hundreds of people.", "choices": ["automatic", "difficult", "visible", "expensive", "boring"], "answer": 1, "answer_text": "", "explanation": "연습을 거듭할수록 기술이 몸에 배어 압박 속에서도 유지된다는 흐름이므로 ①이 정답이다.", "evidence": ["Musicians, for example, keep practicing a piece long after they can play it without mistakes."], "rubric": [], "flags": ["answer_leak"]}, {"id": "s10", "paperId": "s-en", "unitId": "u04", "group": "writing", "subtype": "주제문 쓰기", "form": "서답", "stem": "윗글의 주제를 우리말 30자 이내로 쓰시오.", "choices": [], "answer": 0, "answer_text": "한 번 해낸 뒤에도 계속 연습해야 기술이 몸에 밴다.", "explanation": "한 번 할 수 있는 것과 잘하는 것은 다르며, 반복 연습이 기술을 자동화한다는 내용이다.", "evidence": ["Each extra round of practice makes the skill more automatic, so that it holds up even under pressure, such as on a stage in front of hundreds of people."], "rubric": [{"point": 3, "criterion": "한 번 해낸 뒤에도 연습을 계속해야 한다는 내용"}, {"point": 2, "criterion": "연습이 기술을 몸에 배게(자동화) 한다는 내용"}], "flags": []}, {"id": "s11", "paperId": "s-en", "unitId": "u05", "group": "original", "subtype": "순서", "form": "5지", "stem": "주어진 글 다음에 이어질 글의 순서로 가장 적절한 것을 고르시오.\n\nMost people think of forgetting as a simple failure of memory.\n\n(A) It clears away details we rarely use, such as the color of a stranger's shirt, to make room for new information.\n\n(B) As a result, the important ideas stand out more clearly, and we can find them faster when we need them.\n\n(C) Scientists, however, now believe that the brain often forgets on purpose.", "choices": ["(A) - (C) - (B)", "(B) - (A) - (C)", "(B) - (C) - (A)", "(C) - (A) - (B)", "(C) - (B) - (A)"], "answer": 4, "answer_text": "", "explanation": "however 로 통념을 뒤집는 (C), 그 방법을 설명하는 (A), 결과를 말하는 (B) 순서이므로 ④가 정답이다.", "evidence": ["Scientists, however, now believe that the brain often forgets on purpose."], "rubric": [], "flags": []}, {"id": "s12", "paperId": "s-ko", "unitId": "u01", "group": "fact", "subtype": "내용 일치", "form": "5지", "stem": "윗글의 내용으로 적절하지 <u>않은</u> 것은?", "choices": ["확증 편향은 정보를 빠르게 처리하게 하는 면이 있다.", "확증 편향은 잘못된 판단을 굳히는 원인이 될 수 있다.", "확증 편향이 있는 사람은 반대 연구 결과를 가볍게 넘기기 쉽다.", "확증 편향을 줄이려면 반대 근거를 일부러 찾아보는 태도가 필요하다.", "반대 근거를 찾아보면 자신의 믿음은 반드시 약해진다."], "answer": 5, "answer_text": "", "explanation": "믿음이 반대 근거 앞에서도 유지되면 오히려 단단해진다고 했으므로 ⑤가 적절하지 않다.", "evidence": ["자신의 믿음이 반대 근거 앞에서도 유지된다면 그 믿음은 이전보다 단단해진다."], "rubric": [], "flags": []}, {"id": "s13", "paperId": "s-ko", "unitId": "u01", "group": "apply", "subtype": "구체적 사례 적용", "form": "5지", "stem": "윗글을 바탕으로 <보기>의 민수에게 해 줄 조언으로 가장 적절한 것은?\n<보기>\n민수는 아침 운동이 공부 집중력을 높인다고 믿고 있다. 그는 이 생각을 뒷받침하는 글 세 편을 찾아 친구들에게 보여 주었다.", "choices": ["뒷받침하는 글을 더 많이 모으면 판단이 정확해질 거야.", "아침 운동이 집중력과 관계없다는 연구도 찾아보고 그 근거를 따져 봐.", "친구들의 의견은 듣지 말고 네 생각을 지켜.", "믿음을 빨리 정하는 것이 확증 편향을 줄이는 길이야.", "반대 근거는 대개 틀렸으니 읽지 않아도 돼."], "answer": 2, "answer_text": "", "explanation": "확증 편향을 줄이려면 반대되는 근거를 의도적으로 찾아 점검해야 하므로 ②가 정답이다.", "evidence": ["이러한 편향을 줄이려면 자신의 생각과 반대되는 근거를 의도적으로 찾아보고, 그 근거가 왜 틀렸는지 설명할 수 있는지 스스로 점검하는 태도가 필요하다."], "rubric": [], "flags": []}, {"id": "s14", "paperId": "s-ko", "unitId": "u01", "group": "vocab", "subtype": "바꿔 쓰기", "form": "4지", "stem": "윗글의 '대수롭지 않게'와 바꿔 쓰기에 가장 적절한 것은?", "choices": ["중요하지 않게", "조심스럽게", "반갑게", "자세하게"], "answer": 1, "answer_text": "", "explanation": "'대수롭지 않다'는 중요하게 여길 만하지 않다는 뜻이므로 ①이 정답이다.", "evidence": ["예를 들어 어떤 음식이 건강에 좋다고 믿는 사람은 그 음식의 효과를 다룬 기사만 골라 읽고, 반대되는 연구 결과는 대수롭지 않게 넘기기 쉽다."], "rubric": [], "flags": []}, {"id": "s15", "paperId": "s-ko", "unitId": "u01", "group": "writing", "subtype": "요약 쓰기", "form": "서답", "stem": "윗글에서 확증 편향을 줄이는 방법을 찾아 40자 이내로 쓰시오.", "choices": [], "answer": 0, "answer_text": "자신의 생각과 반대되는 근거를 의도적으로 찾아보고 스스로 점검한다.", "explanation": "넷째 문장에 확증 편향을 줄이는 방법이 제시되어 있다.", "evidence": ["이러한 편향을 줄이려면 자신의 생각과 반대되는 근거를 의도적으로 찾아보고, 그 근거가 왜 틀렸는지 설명할 수 있는지 스스로 점검하는 태도가 필요하다."], "rubric": [{"point": 3, "criterion": "반대되는 근거를 찾아본다는 내용"}, {"point": 2, "criterion": "스스로 점검한다는 내용"}], "flags": []}, {"id": "s16", "paperId": "s-ko", "unitId": "u02", "group": "lit", "subtype": "표현상 특징", "form": "5지", "stem": "윗글의 표현상 특징으로 가장 적절한 것은?", "choices": ["사물을 사람처럼 표현하여 쓸쓸한 분위기를 드러내고 있다.", "반어적 표현으로 화자의 기쁨을 강조하고 있다.", "명령형 어조로 대상에 대한 의지를 드러내고 있다.", "계절의 변화에 따라 시상을 전개하고 있다.", "대화 형식으로 화자와 청자의 갈등을 보여 주고 있다."], "answer": 1, "answer_text": "", "explanation": "우체통이 '입을 다물고', 바람이 '입술을 두드리고', 창문들이 '안부를 묻는다'고 표현했으므로 ①이 적절하다.", "evidence": ["바람만 그 입술을 두드리고 간다"], "rubric": [], "flags": []}, {"id": "s17", "paperId": "s-ko", "unitId": "u02", "group": "lit", "subtype": "시어 · 시구 의미", "form": "5지", "stem": "'접힌 종이'에 대한 이해로 가장 적절한 것은?", "choices": ["화자가 끝내 보내지 못한 마음을 담은 편지이다.", "화자가 우체통에서 꺼낸 오래된 편지이다.", "화자가 이웃에게 받은 안부 쪽지이다.", "화자가 길에서 주운 광고지이다.", "화자가 버리려고 가져온 영수증이다."], "answer": 1, "answer_text": "", "explanation": "주머니 속 접힌 종이를 만지작거리다 우체통에 넣지 못하고 돌아서므로 ①이 적절하다.", "evidence": ["나는 주머니 속 접힌 종이를 만지작거리다", "끝내 넣지 못한 채 돌아선다"], "rubric": [], "flags": []}, {"id": "s18", "paperId": "s-ko", "unitId": "u02", "group": "writing", "subtype": "근거 찾아 쓰기", "form": "서답", "stem": "화자가 편지를 부치지 못했음을 알 수 있는 시구를 윗글에서 찾아 그대로 쓰시오.", "choices": [], "answer": 0, "answer_text": "끝내 넣지 못한 채 돌아선다", "explanation": "여섯째 행에서 우체통에 넣지 못하고 돌아섰다고 했다.", "evidence": ["끝내 넣지 못한 채 돌아선다"], "rubric": [{"point": 3, "criterion": "'끝내 넣지 못한 채 돌아선다'를 정확히 씀"}], "flags": []}]};
